mapper.select:
SELECT t.id AS id, t.ticket_no AS ticketNo, t.title AS title, t.ticket_type AS ticketType, t.priority AS priority, t.status AS status, t.related_order_id AS relatedOrderId, t.assigned_to AS assignedTo, t.organization_id AS organizationId, t.create_time AS createTime, t.close_time AS closeTime FROM ad_support_ticket t WHERE t.organization_id = #{request.organizationId} AND t.deleted = 0
AND t.ticket_type = #{request.ticketType}
AND t.priority = #{request.priority}
AND t.status = #{request.status}
AND (t.ticket_no LIKE CONCAT('%', #{request.keyword}, '%') OR t.title LIKE CONCAT('%', #{request.keyword}, '%'))
